#include "tasks/ManualProcedureLearnerSchemas.hpp"
#include "tasks/ManualProcedureSourcePolicies.hpp"
#include <functional>
namespace fathom::tasks::manual_procedure_graph_support {
namespace {using V=json::Value;using O=V::Object;using A=V::Array;
const V& f(const V& v,const char* n){const auto* x=v.find(n);if(!x)throw recipes::Error("LEARNER_SCHEMA_FIELD");return *x;}
std::string label(const V& domain,const V& key){if(key.null())return "Unknown report";if(!key.isString()||!domain.isObject()||!domain.find("records"))return key.isString()?key.string():json::stringify(key);for(const auto& row:f(domain,"records").array())if(f(row,"source_key")==key){std::string text=f(row,"root").string()+" "+f(row,"quality").string()+" · "+f(row,"inversion").string()+" inversion";for(const auto& member:f(row,"members").array())text+=" · "+f(member,"printed_note").string()+" (string "+json::stringify(f(member,"string"))+", fret "+json::stringify(f(member,"fret"))+")";return text;}return key.string();}
}
V candidateLearnerSchema(const V& source,const V& program,const std::string& node,const O& saved){const auto& graph=f(program,"graph");const auto* domain=f(graph,"domains").find("source_triad42");V expected(O{});if(!node.empty()){const auto* n=f(graph,"nodes").find(node);if(n){if(n->find("expected"))expected=f(*n,"expected");if(domain){if(const auto* p=n->find("schema_projection"))expected=derivedExpectedReports(*p,saved,*domain);else if(const auto* guards=n->find("constraints"))for(const auto& c:guards->array())if(f(c,"kind")==V("selected_source_pattern_reports"))expected=futurePatternProjection(f(c,"projection"),saved,*domain);}}}
 std::function<V(const V&,const V*)> visit=[&](const V& input,const V* report)->V {auto out=input;if(const auto* labels=input.find("enum_labels")){if(!input.find("enum")||!labels->isArray()||labels->array().size()!=f(input,"enum").array().size())throw recipes::Error("CLOSED_LEARNER_CHOICE_LABELS");out.object()["enumLabels"]=*labels;out.object().erase("enum_labels");}
  if(const auto* choices=input.find("enum")){A labels;bool sourceShapes=false;for(const auto& key:choices->array()){const auto readable=domain?label(*domain,key):(key.isString()?key.string():json::stringify(key));sourceShapes=sourceShapes||(key.isString()&&readable!=key.string());labels.emplace_back(readable);}if(sourceShapes)out.object()["enumLabels"]=labels;}
  if(const auto* props=input.find("properties"))for(const auto& field:props->object()){const auto* fact=report&&report->isObject()?report->find(field.first):nullptr;auto child=visit(field.second,fact);if(field.first=="reported_shape_key"&&fact&&domain&&fact->isString()){const auto readable=label(*domain,*fact);if(readable!=fact->string()){child.object()["enum"]=A{*fact,nullptr};child.object()["enumLabels"]=A{readable,"Unknown performed shape"};child.object()["title"]="Reported source shape";child.object()["description"]="Choose your actual report explicitly; this is not a performed-shape default.";}}out.object()["properties"].object()[field.first]=child;}
  if(const auto* items=input.find("items"))out.object()["items"]=visit(*items,nullptr);return out;};return visit(source,&expected);
}
}
